  rs as (insert into madplan.recipe_steps (recipe_id, sort_order, text, timer_minutes, section) select r.id, v.ord, v.txt, v.timer, v.sec from r, (values (0, 'Sæt risene over efter anvisningen på pakken.', null::int, null), (1, 'Smelt smørret i en gryde og brun kyllingen let. Tag den op.', null::int, null), (2, 'Svits løg og æble i gryden, til løget er blankt. Drys karry over og rist et minut, så krydderiet folder sig ud.', null::int, null), (3, 'Rør melet i, og tilsæt vand og bouillon lidt ad gangen under omrøring.', null::int, null), (4, 'Kom kyllingen tilbage og lad det simre under låg.', 15::int, null), (5, 'Rør fløden i, varm igennem og smag til med salt og peber. Server med risene.', null::int, null)) v(ord, txt, timer, sec))
