  rs as (insert into madplan.recipe_steps (recipe_id, sort_order, text, timer_minutes, section) select r.id, v.ord, v.txt, v.timer, v.sec from r, (values (0, 'Opløs gæren i den lune mælk. Rør sukker, salt, smør og æg i, og ælt melet i lidt ad gangen til en blød, smidig dej. Lad hæve tildækket.', 45::int, 'Boller'), (1, 'Form 6–8 boller, sæt dem på en plade med bagepapir og tryk dem lidt flade. Lad dem efterhæve.', 30::int, 'Boller'), (2, 'Pensl med sammenpisket æg, drys sesam over og bag ved 200 °C.', 14::int, 'Boller'), (3, 'Form kødet til 4 bøffer, lidt bredere end bollerne, og lav en lille fordybning i midten. Krydr med salt og peber lige før stegning.', null::int, 'Bøffer'), (4, 'Steg bøfferne på en meget varm pande eller grill, ca. 3 minutter på hver side. Læg osten på det sidste minut.', 6::int, 'Bøffer'), (5, 'Rist bollerne let på snitfladen og saml burgerne med salat, tomat, løg, agurk og sauce.', null::int, 'Fyld')) v(ord, txt, timer, sec))
