  rs as (insert into madplan.recipe_steps (recipe_id, sort_order, text, timer_minutes, section) select r.id, v.ord, v.txt, v.timer, v.sec from r, (values (0, 'Kog æggene i præcis 6½ minut og læg dem i isvand. Pil dem og læg dem i soya fortyndet med lidt vand.', 7::int, 'Æg'), (1, 'Kog vand, bouillon, hvidløg og ingefær op. Kom kyllingelårene i og lad dem simre, til de er møre.', 25::int, 'Bouillon'), (2, 'Tag kyllingen op og skær den i skiver eller riv den fra hinanden. Rør soya, miso og sesamolie i bouillonen.', null::int, 'Bouillon'), (3, 'Kog nudlerne efter anvisningen, og blancher pak choi kort i bouillonen.', 3::int, 'Servering'), (4, 'Fordel nudler i skåle, hæld bouillon over og top med kylling, pak choi, halverede æg, forårsløg, sesam og sriracha.', null::int, 'Servering')) v(ord, txt, timer, sec))
